-- Additive OKF migration. Existing requests, rules and application data are preserved.
-- Run once in the existing Supabase project's SQL editor as the database owner.
begin;
-- Some installations only used the old browser fallback. Create the existing
-- request store when absent; never replace or modify existing request rows.
create table if not exists public.madagascar_bsc_requests (
  id text primary key, reference text not null, country text not null default '',
  status text not null default 'Needs review', documents jsonb not null default '[]',
  analysis jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
alter table public.madagascar_bsc_requests add column if not exists country text not null default '';
alter table public.madagascar_bsc_requests enable row level security;
create policy okf_authenticated_requests on public.madagascar_bsc_requests for all to authenticated using (true) with check (true);
grant select,insert,update,delete on public.madagascar_bsc_requests to authenticated;
insert into storage.buckets(id,name,public) values('madagascar-bsc','madagascar-bsc',false) on conflict(id) do nothing;
create policy okf_request_documents_read on storage.objects for select to authenticated using(bucket_id='madagascar-bsc');
create policy okf_request_documents_insert on storage.objects for insert to authenticated with check(bucket_id='madagascar-bsc');
create policy okf_request_documents_update on storage.objects for update to authenticated using(bucket_id='madagascar-bsc') with check(bucket_id='madagascar-bsc');
create table if not exists public.okf_state (
  id boolean primary key default true check (id), generation integer not null default 0,
  pages jsonb not null check (jsonb_typeof(pages) = 'array')
);
create table if not exists public.okf_form_schema (
  id boolean primary key default true check (id), presentation jsonb not null
);
alter table public.okf_form_schema enable row level security;
revoke all on public.okf_form_schema from public,anon,authenticated;
create table if not exists public.okf_drafts (
  id uuid primary key, edit_version integer not null default 1,
  base_generation integer not null, changes jsonb not null,
  reason text not null, source text not null default '', proposer uuid not null,
  status text not null default 'pending' check (status in ('pending','published','discarded')),
  review text not null default '', review_edit integer,
  updated_at timestamptz not null default now()
);
create table if not exists public.okf_publications (
  id uuid primary key default gen_random_uuid(), draft_id uuid not null unique references public.okf_drafts(id),
  before_pages jsonb not null, after_pages jsonb not null, proposer uuid not null, approver uuid not null,
  reason text not null, source text not null, created_at timestamptz not null default now()
);
create table if not exists public.okf_reviews (
  id uuid primary key, request_id text not null, review jsonb not null,
  actor uuid not null default auth.uid(), created_at timestamptz not null default now()
);
create index if not exists okf_reviews_request on public.okf_reviews(request_id, created_at desc);
create table if not exists public.okf_corrections (
  id uuid primary key default gen_random_uuid(), request_id text not null,
  review_id uuid references public.okf_reviews(id), target text not null,
  before_value jsonb, after_value jsonb not null, reason text not null,
  actor uuid not null, created_at timestamptz not null default now()
);
create index if not exists okf_corrections_request on public.okf_corrections(request_id, created_at);
create table if not exists public.okf_intake (
  id uuid primary key default gen_random_uuid(), page_id text not null, note text not null,
  sources jsonb not null default '[]', result jsonb not null,
  actor uuid not null default auth.uid(), created_at timestamptz not null default now()
);

-- This application grants authenticated staff access to certificate processing.
-- A server-managed app_metadata.okf_role of viewer makes OKF access read-only.
create or replace function public.okf_can_edit() returns boolean
language sql stable security invoker set search_path = '' as $$
  select auth.uid() is not null and coalesce(auth.jwt()->'app_metadata'->>'okf_role','staff') in ('staff','editor','publisher','admin');
$$;
create or replace function public.okf_can_publish() returns boolean
language sql stable security invoker set search_path = '' as $$
  select auth.uid() is not null and coalesce(auth.jwt()->'app_metadata'->>'okf_role','staff') in ('staff','publisher','admin');
$$;

alter table public.okf_state enable row level security;
alter table public.okf_drafts enable row level security;
alter table public.okf_publications enable row level security;
alter table public.okf_reviews enable row level security;
alter table public.okf_corrections enable row level security;
alter table public.okf_intake enable row level security;
create policy okf_intake_read on public.okf_intake for select to authenticated using (true);
create policy okf_intake_insert on public.okf_intake for insert to authenticated with check (public.okf_can_edit() and actor=auth.uid());
grant select,insert on public.okf_intake to authenticated;
revoke all on public.okf_intake from anon;
create policy okf_state_read on public.okf_state for select to authenticated using (true);
create policy okf_drafts_read on public.okf_drafts for select to authenticated using (true);
create policy okf_publications_read on public.okf_publications for select to authenticated using (true);
create policy okf_reviews_read on public.okf_reviews for select to authenticated using (true);
create policy okf_reviews_insert on public.okf_reviews for insert to authenticated with check (public.okf_can_edit() and actor = auth.uid() and review->>'id' = id::text and review->>'requestId' = request_id);
create policy okf_corrections_read on public.okf_corrections for select to authenticated using (true);
grant select on public.okf_state, public.okf_drafts, public.okf_publications, public.okf_reviews, public.okf_corrections to authenticated;
grant insert on public.okf_reviews to authenticated;
revoke all on public.okf_state, public.okf_drafts, public.okf_publications, public.okf_reviews, public.okf_corrections from anon;

-- The database revalidates invariants, including direct RPC calls that bypass HTTP.
create or replace function public.okf_text_properties(p_object jsonb,p_names text[]) returns boolean
language sql immutable set search_path = '' as $$
  select jsonb_typeof(p_object)='object' and not exists(select 1 from unnest(p_names) k where jsonb_typeof(p_object->k) is distinct from 'string' or length(p_object->>k)>12000)
$$;
create or replace function public.okf_string_array(p_value jsonb,p_ids boolean default true) returns boolean
language plpgsql immutable set search_path = '' as $$
begin
  if jsonb_typeof(p_value) is distinct from 'array' then return false; end if;
  return jsonb_array_length(p_value)<=300 and not exists(select 1 from jsonb_array_elements(p_value) x where jsonb_typeof(x)<>'string' or length(x#>>'{}')>case when p_ids then 160 else 12000 end or (p_ids and length(x#>>'{}')=0));
end; $$;
revoke all on function public.okf_text_properties(jsonb,text[]),public.okf_string_array(jsonb,boolean) from public,anon,authenticated;
create or replace function public.okf_validate_pages(p_pages jsonb,p_published_only boolean default false) returns void
language plpgsql security definer set search_path = '' as $$
#variable_conflict use_column
declare p jsonb; r jsonb; f jsonb; m jsonb; item jsonb; ref text; allowed_ids text[]; field_ids text[]; rule_ids text[]; source_ids text[]; mapping_ids text[]; system_ids text[];
begin
  select array_agg(x->>'id') into system_ids from public.okf_form_schema s cross join lateral jsonb_array_elements(s.presentation) x;
  select array_agg(x->>'id') into field_ids from jsonb_array_elements(p_pages) p cross join lateral jsonb_array_elements(p->'content'->'fields') x where not p_published_only or (p->>'revision')::integer>0;
  select array_agg(x->>'id') into rule_ids from jsonb_array_elements(p_pages) p cross join lateral jsonb_array_elements(p->'content'->'rules') x where not p_published_only or (p->>'revision')::integer>0;
  select array_agg(x->>'id') into source_ids from jsonb_array_elements(p_pages) p cross join lateral jsonb_array_elements(p->'content'->'sources') x where not p_published_only or (p->>'revision')::integer>0;
  select array_agg(x->>'id') into mapping_ids from jsonb_array_elements(p_pages) p cross join lateral jsonb_array_elements(p->'content'->'mappings') x where not p_published_only or (p->>'revision')::integer>0;
  select array_agg(p->>'id') into allowed_ids from jsonb_array_elements(p_pages) p where not p_published_only or (p->>'revision')::integer>0;
  allowed_ids := coalesce(allowed_ids,'{}') || coalesce(field_ids,'{}') || coalesce(rule_ids,'{}') || coalesce(source_ids,'{}') || coalesce(mapping_ids,'{}');
  if cardinality(allowed_ids) <> (select count(distinct x) from unnest(allowed_ids) x) then raise exception 'Duplicate stable ID'; end if;
  if exists(select 1 from jsonb_array_elements(p_pages) p cross join lateral jsonb_array_elements(p->'content'->'rules') r group by r->>'country',r->>'document',r->>'kind',r->>'stage',lower(regexp_replace(r->>'condition','[^a-zA-Z0-9]+',' ','g')),lower(regexp_replace(r->>'instruction','[^a-zA-Z0-9]+',' ','g')) having count(*)>1) then raise exception 'Already covered. Reference the existing rule.'; end if;
  for p in select value from jsonb_array_elements(p_pages) loop
    if p_published_only and (p->>'revision')::integer=0 then continue; end if;
    if jsonb_typeof(p->'content'->'sections') is distinct from 'array' or jsonb_typeof(p->'content'->'rules') is distinct from 'array' or jsonb_typeof(p->'content'->'fields') is distinct from 'array' or jsonb_typeof(p->'content'->'mappings') is distinct from 'array' or jsonb_typeof(p->'content'->'sources') is distinct from 'array' or jsonb_typeof(p->'content'->'aliases') is distinct from 'array' then raise exception 'Invalid content schema'; end if;
    if not public.okf_string_array(p->'content'->'aliases',false) or jsonb_array_length(p->'content'->'aliases')>100 or jsonb_array_length(p->'content'->'sections')>30 or jsonb_array_length(p->'content'->'rules')>300 or jsonb_array_length(p->'content'->'fields')>300 or jsonb_array_length(p->'content'->'mappings')>300 or jsonb_array_length(p->'content'->'sources')>100 then raise exception 'Content limit exceeded'; end if;
    for item in select value from jsonb_array_elements(p->'content'->'sections') loop
      if not public.okf_text_properties(item,array['heading','text']) or not public.okf_string_array(item->'references') then raise exception 'Invalid section'; end if;
    end loop;
    for item in select value from jsonb_array_elements((p->'content'->'rules') || (p->'content'->'fields') || (p->'content'->'mappings') || (p->'content'->'sources')) loop
      if not public.okf_text_properties(item,array['id']) or length(item->>'id') not between 1 and 160 then raise exception 'Invalid stable ID'; end if;
    end loop;
    for item in select value from jsonb_array_elements(p->'content'->'sources') loop
      if not public.okf_text_properties(item,array['title','url','attachmentPath','note']) then raise exception 'Invalid source'; end if;
      if item->>'url'<>'' and item->>'url' !~* '^https?://' and item->>'url'<>'/madagascar-bsc/invoice_template_En.xlsx' then raise exception 'Invalid source URL'; end if;
      if item->>'attachmentPath'<>'' and item->>'attachmentPath' !~ '^evidence/[a-zA-Z0-9_-]+/[a-zA-Z0-9_.-]+$' then raise exception 'Invalid evidence path'; end if;
    end loop;
    for ref in select jsonb_array_elements_text(s->'references') from jsonb_array_elements(p->'content'->'sections') s loop
      if not (ref=any(allowed_ids)) then raise exception 'Unknown or unpublished reference: %',ref; end if;
    end loop;
    for r in select value from jsonb_array_elements(p->'content'->'rules') loop
      if not public.okf_text_properties(r,array['country','document','instruction','requirement','condition','stage','consequence','effectiveFrom','effectiveTo','kind']) or not public.okf_string_array(r->'sourceIds') or not public.okf_text_properties(r->'check',array['operator','expected']) or not public.okf_string_array(r->'check'->'fieldIds') then raise exception 'Invalid rule schema'; end if;
      if r->>'kind' not in ('document','acceptance','comparison','format') or r->'check'->>'operator' not in ('interpret','present','equal','number','date','option') then raise exception 'Unknown check'; end if;
      if r->>'country' is distinct from p->>'country' or p->>'country'='Shared' or (p->>'template'='document' and r->>'document' is distinct from p->>'title') then raise exception 'Country or document scope mismatch'; end if;
      if r->>'requirement' is null or r->>'requirement' not in ('always required','conditionally required','not required','unconfirmed') or r->>'stage' is null or r->>'stage' not in ('intake','drafting','submission','validation','release') then raise exception 'Invalid requirement or stage'; end if;
      if r->>'requirement'<>'unconfirmed' and coalesce(jsonb_array_length(r->'sourceIds'),0)=0 then raise exception 'Evidence is required'; end if;
      for ref in select jsonb_array_elements_text(r->'sourceIds') loop
        if not (ref=any(coalesce(source_ids,'{}'))) then raise exception 'Unknown or unpublished source'; end if;
      end loop;
      for ref in select jsonb_array_elements_text(r->'check'->'fieldIds') loop
        if not (ref=any(coalesce(field_ids,'{}'))) then raise exception 'Unknown or unpublished extraction field'; end if;
      end loop;
      if nullif(r->>'effectiveFrom','') is not null then perform (r->>'effectiveFrom')::date; end if;
      if nullif(r->>'effectiveTo','') is not null then perform (r->>'effectiveTo')::date; end if;
      if nullif(r->>'effectiveFrom','') is not null and nullif(r->>'effectiveTo','') is not null and (r->>'effectiveFrom')::date>(r->>'effectiveTo')::date then raise exception 'Invalid effective date range'; end if;
    end loop;
    for f in select value from jsonb_array_elements(p->'content'->'fields') loop
      if not public.okf_text_properties(f,array['label','document','location','requiredWhen','instruction']) or not public.okf_string_array(f->'portalFieldIds') or not public.okf_string_array(f->'ruleIds') then raise exception 'Invalid extraction field schema'; end if;
      if p->>'template'<>'document' or f->>'document' is distinct from p->>'title' then raise exception 'Extraction fields belong to document pages'; end if;
      for ref in select jsonb_array_elements_text(f->'portalFieldIds') loop
        if not (ref=any(coalesce(system_ids,'{}'))) then raise exception 'Unknown portal field'; end if;
      end loop;
      for ref in select jsonb_array_elements_text(f->'ruleIds') loop
        if not (ref=any(coalesce(rule_ids,'{}'))) then raise exception 'Unknown or unpublished rule'; end if;
      end loop;
    end loop;
    if (select count(distinct x->>'systemFieldId') from jsonb_array_elements(p->'content'->'mappings') x) <> jsonb_array_length(p->'content'->'mappings') then raise exception 'Duplicate portal mapping'; end if;
    for m in select value from jsonb_array_elements(p->'content'->'mappings') loop
      if not public.okf_text_properties(m,array['systemFieldId','entryRule','ifMissing','transform','unit']) or not public.okf_string_array(m->'sourceFieldIds') or not public.okf_string_array(m->'fallbackSourceIds') or not public.okf_string_array(m->'ruleIds') or jsonb_typeof(m->'repeated') is distinct from 'boolean' or m->>'transform' not in ('none','trim','uppercase','decimal','date-iso') or jsonb_array_length(m->'sourceFieldIds')=0 then raise exception 'Invalid mapping schema'; end if;
      if p->>'template'<>'mappings' or not (m->>'systemFieldId'=any(coalesce(system_ids,'{}'))) then raise exception 'Invalid portal mapping'; end if;
      for ref in select jsonb_array_elements_text((m->'sourceFieldIds') || (m->'fallbackSourceIds')) loop
        if not (ref=any(coalesce(field_ids,'{}'))) then raise exception 'Unknown or unpublished mapping source'; end if;
        if not exists(select 1 from jsonb_array_elements(p_pages) fp cross join lateral jsonb_array_elements(fp->'content'->'fields') ff where ff->>'id'=ref and fp->>'country'=p->>'country' and (ff->'portalFieldIds') ? (m->>'systemFieldId')) then raise exception 'Mapping must have a reciprocal field reference in the same country'; end if;
      end loop;
      for ref in select jsonb_array_elements_text(m->'ruleIds') loop
        if not (ref=any(coalesce(rule_ids,'{}'))) then raise exception 'Unknown or unpublished mapping rule'; end if;
      end loop;
    end loop;
  end loop;
end; $$;
revoke all on function public.okf_validate_pages(jsonb,boolean) from public,anon,authenticated;

create or replace function public.okf_save_draft(p_id uuid, p_expected_edit integer, p_base_generation integer, p_changes jsonb, p_reason text, p_source text)
returns jsonb language plpgsql security definer set search_path = '' as $$
#variable_conflict use_column
declare s public.okf_state; d public.okf_drafts; c jsonb; p jsonb; candidate jsonb;
begin
  if not public.okf_can_edit() then raise exception 'Staff editing permission required'; end if;
  select * into strict s from public.okf_state where id for update;
  if s.generation <> p_base_generation then raise exception 'Knowledge changed. Refresh comparison before saving.'; end if;
  if length(trim(p_reason)) = 0 or jsonb_typeof(p_changes) <> 'array' or jsonb_array_length(p_changes) not between 1 and 30 then raise exception 'Invalid change set'; end if;
  if (select count(distinct x->>'pageId') from jsonb_array_elements(p_changes) x) <> jsonb_array_length(p_changes) then raise exception 'Duplicate page'; end if;
  for c in select value from jsonb_array_elements(p_changes) loop
    select value into p from jsonb_array_elements(s.pages) where value->>'id' = c->>'pageId';
    if p is null or c->>'level' is null or c->>'level' not in ('patch','minor') then raise exception 'Unknown page or release level'; end if;
    if (select jsonb_agg(x->>'heading') from jsonb_array_elements(p->'content'->'sections') x) is distinct from
       (select jsonb_agg(x->>'heading') from jsonb_array_elements(c->'content'->'sections') x) then raise exception 'Structural changes require a separate release'; end if;
    if c->>'level' = 'patch' and ((p->'content') - 'sections' - 'sources') is distinct from ((c->'content') - 'sections' - 'sources') then raise exception 'Operational changes require minor release'; end if;
    if jsonb_typeof(c->'content'->'rules') <> 'array' or jsonb_typeof(c->'content'->'fields') <> 'array' or jsonb_typeof(c->'content'->'mappings') <> 'array' or jsonb_typeof(c->'content'->'sources') <> 'array' then raise exception 'Invalid content'; end if;
    if exists(select 1 from jsonb_array_elements(c->'content'->'rules') r where r->>'country' is distinct from p->>'country' or (p->>'template' = 'document' and r->>'document' is distinct from p->>'title') or r->>'stage' not in ('intake','drafting','submission','validation','release') or r->>'requirement' not in ('always required','conditionally required','not required','unconfirmed') or (r->>'requirement' <> 'unconfirmed' and jsonb_array_length(r->'sourceIds') = 0)) then raise exception 'Invalid rule scope, stage or evidence'; end if;
  end loop;
  select jsonb_agg(case when c is not null then p || jsonb_build_object('content',c->'content') else p end) into candidate from jsonb_array_elements(s.pages) p left join lateral (select x as c from jsonb_array_elements(p_changes) x where x->>'pageId'=p->>'id') changes on true;
  perform public.okf_validate_pages(candidate,false);
  select * into d from public.okf_drafts where id = p_id for update;
  if found then
    if d.proposer <> auth.uid() or d.status <> 'pending' or d.edit_version <> p_expected_edit then raise exception 'Draft changed or belongs to another staff member'; end if;
    if d.changes = p_changes and d.reason = p_reason and d.source = p_source then return to_jsonb(d); end if;
    update public.okf_drafts set changes=p_changes, reason=p_reason, source=p_source, edit_version=edit_version+1, review='', review_edit=null, updated_at=now() where id=p_id returning * into d;
  else
    if p_expected_edit <> 0 then raise exception 'Draft no longer exists'; end if;
    insert into public.okf_drafts(id,base_generation,changes,reason,source,proposer) values(p_id,p_base_generation,p_changes,p_reason,p_source,auth.uid()) returning * into d;
  end if;
  return to_jsonb(d);
end; $$;

create or replace function public.okf_preview(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
#variable_conflict use_column
declare d public.okf_drafts; s public.okf_state;
begin
  if auth.uid() is null then raise exception 'Sign in required'; end if;
  select * into strict s from public.okf_state where id;
  select * into strict d from public.okf_drafts where id=p_id;
  if d.status <> 'pending' then raise exception 'Draft is not pending'; end if;
  return jsonb_build_object('draft',to_jsonb(d),'state',to_jsonb(s),'token',md5(d.changes::text || d.reason || d.source || d.edit_version::text || s.generation::text));
end; $$;

create or replace function public.okf_publish(p_id uuid, p_token text) returns jsonb
language plpgsql security definer set search_path = '' as $$
#variable_conflict use_column
declare d public.okf_drafts; s public.okf_state; p jsonb; c jsonb; result jsonb := '[]'; before_changed jsonb := '[]'; after_changed jsonb := '[]'; v text; parts text[]; publication public.okf_publications;
begin
  if not public.okf_can_publish() then raise exception 'Publication permission required'; end if;
  select * into strict s from public.okf_state where id for update;
  select * into strict d from public.okf_drafts where id=p_id for update;
  if d.status <> 'pending' or s.generation <> d.base_generation or p_token is distinct from md5(d.changes::text || d.reason || d.source || d.edit_version::text || s.generation::text) then raise exception 'Comparison is stale. Refresh before approval.'; end if;
  for p in select value from jsonb_array_elements(s.pages) loop
    select value into c from jsonb_array_elements(d.changes) where value->>'pageId'=p->>'id';
    if c is not null and ((p->>'revision')::integer = 0 or c->'content' is distinct from p->'content') then
      before_changed := before_changed || jsonb_build_array(p);
      if (p->>'revision')::integer = 0 then v := '1.0.0';
      else
        parts := string_to_array(p->>'version','.');
        if c->>'level'='patch' then v := parts[1] || '.' || parts[2] || '.' || ((parts[3])::integer+1)::text;
        else v := parts[1] || '.' || ((parts[2])::integer+1)::text || '.0'; end if;
      end if;
      p := p || jsonb_build_object('content',c->'content','revision',(p->>'revision')::integer+1,'version',v,'publishedAt',now());
      after_changed := after_changed || jsonb_build_array(p);
    end if;
    result := result || jsonb_build_array(p);
  end loop;
  if jsonb_array_length(after_changed)=0 then raise exception 'Already covered. No content changes to publish.'; end if;
  perform public.okf_validate_pages(result,true);
  -- All page updates and history become visible in the same transaction.
  update public.okf_state set pages=result,generation=generation+1 where id;
  insert into public.okf_publications(draft_id,before_pages,after_pages,proposer,approver,reason,source) values(d.id,before_changed,after_changed,d.proposer,auth.uid(),d.reason,d.source) returning * into publication;
  update public.okf_drafts set status='published',updated_at=now() where id=p_id;
  return to_jsonb(publication);
end; $$;

create or replace function public.okf_draft_action(p_id uuid,p_edit integer,p_action text,p_review text default '') returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.okf_can_edit() then raise exception 'Staff editing permission required'; end if;
  if p_action not in ('discard','review') then raise exception 'Invalid draft action'; end if;
  update public.okf_drafts set status=case when p_action='discard' then 'discarded' else status end,
    review=case when p_action='review' then p_review else review end,
    review_edit=case when p_action='review' then p_edit else review_edit end, updated_at=now()
    where id=p_id and proposer=auth.uid() and status='pending' and edit_version=p_edit;
  if not found then raise exception 'Draft changed'; end if;
end; $$;

create or replace function public.okf_correct_request(p_request_id text,p_target text,p_value text,p_reason text,p_expected_updated_at timestamptz,p_review_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
#variable_conflict use_column
declare r public.madagascar_bsc_requests; before_value jsonb; after_value jsonb; next_analysis jsonb; fields jsonb; correction public.okf_corrections; target_index integer; item_key text;
begin
  if not public.okf_can_edit() or length(trim(p_reason))=0 then raise exception 'Staff permission and a correction reason are required'; end if;
  select * into strict r from public.madagascar_bsc_requests where id=p_request_id for update;
  if r.updated_at is distinct from p_expected_updated_at then raise exception 'Request changed. Reload before correcting.'; end if;
  if p_review_id is not null and not exists(select 1 from public.okf_reviews where id=p_review_id and request_id=p_request_id) then raise exception 'Review does not belong to request'; end if;
  next_analysis := r.analysis;
  if p_target like 'finding:%' then
    if p_value not in ('passed','failed','missing','unreadable','conflicting','not applicable','unconfirmed') then raise exception 'Invalid finding status'; end if;
    select f into before_value from public.okf_reviews v cross join lateral jsonb_array_elements(v.review->'findings') f where v.id=p_review_id and f->>'id'=substring(p_target from 9);
    if before_value is null then raise exception 'Unknown finding'; end if;
    after_value := before_value || jsonb_build_object('status',p_value);
    next_analysis := jsonb_set(next_analysis,'{okfOverrides}',coalesce(next_analysis->'okfOverrides','{}') || jsonb_build_object(substring(p_target from 9),after_value));
  elsif p_target like 'invoiceItem:%' then
    target_index := split_part(p_target,':',2)::integer;
    item_key := split_part(p_target,':',3);
    if target_index<0 or item_key not in ('hsCode','description','quantity','unitOfMeasurement','unitPrice','isSecondHand','originCountry') then raise exception 'Unknown invoice item field'; end if;
    before_value := next_analysis->'invoiceItems'->target_index->item_key;
    if before_value is null then raise exception 'Unknown invoice item'; end if;
    after_value := to_jsonb(p_value);
    next_analysis := jsonb_set(next_analysis,array['invoiceItems',target_index::text,item_key],after_value);
  elsif p_target like 'invoiceValue:%' then
    target_index := substring(p_target from 14)::integer;
    if target_index<0 then raise exception 'Unknown invoice value'; end if;
    before_value := next_analysis->'invoiceValues'->target_index;
    if before_value is null then raise exception 'Unknown invoice value'; end if;
    after_value := before_value || jsonb_build_object('value',p_value,'status',case when trim(p_value)='' then 'missing' else 'extracted' end);
    next_analysis := jsonb_set(next_analysis,array['invoiceValues',target_index::text],after_value);
  elsif p_target='missingCorrectionsMessage' then
    before_value := next_analysis->p_target; after_value := to_jsonb(p_value);
    next_analysis := jsonb_set(next_analysis,array[p_target],after_value);
  else
    select f into before_value from jsonb_array_elements(next_analysis->'fields') f where f->>'key'=p_target;
    if before_value is null then raise exception 'Unknown request field'; end if;
    after_value := before_value || jsonb_build_object('value',p_value,'status',case when trim(p_value)='' then 'missing' else 'extracted' end);
    select jsonb_agg(case when f->>'key'=p_target then after_value else f end) into fields from jsonb_array_elements(next_analysis->'fields') f;
    next_analysis := jsonb_set(next_analysis,'{fields}',fields);
  end if;
  if before_value = after_value then return jsonb_build_object('request',to_jsonb(r),'correction',null); end if;
  insert into public.okf_corrections(request_id,review_id,target,before_value,after_value,reason,actor) values(p_request_id,p_review_id,p_target,before_value,after_value,p_reason,auth.uid()) returning * into correction;
  update public.madagascar_bsc_requests set analysis=next_analysis, status='Needs review', updated_at=now() where id=p_request_id returning * into r;
  return jsonb_build_object('request',to_jsonb(r),'correction',to_jsonb(correction));
end; $$;

